        // ----- Config: nested tables -----
        //
        // Each nested table has a `has_X()` presence check (non-throwing) and
        // an `X()` ref accessor that throws only if called when `has_X()` is
        // false — programmer-error semantics, no try/catch on the happy path.
        //
        // `unsafe fn` is cxx's required acknowledgement that the explicit
        // lifetimes on the ref returns are sound — the references are tied
        // to `&Config`, which C++ holds via `rust::Box<Config>`. No unsafe
        // call on the C++ side.
        fn has_server(self: &Config) -> bool;
        unsafe fn server<'a>(self: &'a Config) -> Result<&'a Server>;
        fn has_grpc(self: &Config) -> bool;
        unsafe fn grpc<'a>(self: &'a Config) -> Result<&'a Grpc>;
        fn has_overlay(self: &Config) -> bool;
