        fn port(self: &PortConfig) -> Box<OptionalU16>;
        fn send_queue_limit(self: &PortConfig) -> Box<OptionalU16>;
        fn user(self: &PortConfig) -> Box<OptionalString>;
        fn password(self: &PortConfig) -> Box<OptionalString>;
